mapper.select:
SELECT 
    (SELECT COUNT(*) 
     FROM refund 
     WHERE ORDER_ID = #{orderId} 
       AND REFUND_STATUS NOT IN ('CANCELLED', 'REJECTED')
    ) AS refundCount,
    (SELECT ORDER_STATUS 
     FROM orders 
     WHERE ORDER_ID = #{orderId}
    ) AS currentStatus

mapper.update:
UPDATE orders 
SET ORDER_STATUS = 'REFUND_REQUESTED'
WHERE ORDER_ID = #{orderId} 
  AND USER_ID = #{userId}
  AND ORDER_STATUS IN ('DONE', 'COMPLETED')

UPDATE payment
SET PAY_STATUS = 'REFUNDED'
WHERE PAY_ID = #{payId}
